34	    public void apply(@Val ClaimStatus status, @Val Claim claim, ClaimRepository repository,
35	            PersonRepository people, RateRepository rates, @Val ChangedBy by, Out<ClaimNumber> audited) throws BadRequestException {
36	        ClaimStatus from = claim.getStatus();
37	        if (!from.canBecome(status)) {
38	            throw new BadRequestException("A " + from + " claim cannot become " + status);
39	        }
40	        if (status == ClaimStatus.SETTLED && by.name().equals(claim.getOpenedBy())) {
41	            throw new BadRequestException("The user who opened a claim cannot settle it");
42	        }
43	        Integer had = claim.getNumber();
44	        claim.setStatus(status);
45	        if (status == ClaimStatus.VOID) {
46	            claim.setNumber(null);
47	        }
48	        if (status == ClaimStatus.OPEN) {
49	            claim.setOpenedBy(by.name());
50	        }
51	        if (status == ClaimStatus.SETTLED) {
52	            claim.setSettledDue(dueNow(claim, people, rates));
53	        }
54	        if (!repository.updateStatus(claim, from)) {
