679	import java.sql.PreparedStatement;
680	import java.util.List;
681	import org.springframework.jdbc.core.JdbcTemplate;
682	import org.springframework.jdbc.core.RowMapper;
683	import org.springframework.jdbc.support.GeneratedKeyHolder;
684	import org.springframework.stereotype.Repository;
685	
686	/** The people on each sheet; ids are assigned in the order people are added. */
687	@Repository
688	public class PersonRepository {
689	
690	    private static final RowMapper<Person> ROW = (rs, n) -> new Person(rs.getLong("id"),
691	            rs.getString("sheet_id"), rs.getString("name"), rs.getString("grade"), rs.getLong("version"));
692	
693	    static final String CHANGED = "Someone else has saved this person since you opened it; the form now shows their changes";
694	
695	    static final String NAME_TAKEN = "That name is already in use on this sheet";
696	
697	    private final JdbcTemplate jdbc;
698	
699	    public PersonRepository(JdbcTemplate jdbc) {
700	        this.jdbc = jdbc;
701	    }
702	
703	    /** The sheet's people, in the order they were added. */
704	    public List<Person> list(String sheetId) {
705	        return jdbc.query("SELECT id, sheet_id, name, grade, version FROM person WHERE sheet_id = ? ORDER BY id", ROW, sheetId);
706	    }
707	
708	    public Person find(String sheetId, long id) {
709	        return jdbc.query("SELECT id, sheet_id, name, grade, version FROM person WHERE sheet_id = ? AND id = ?", ROW, sheetId, id)
710	                .stream().findFirst().orElse(null);
711	    }
712	
713	    /** Whether another person on the sheet has this name, ignoring case and surrounding spaces. */
714	    public boolean nameTaken(String sheetId, String name, Long exceptId) {
715	        Integer n = jdbc.queryForObject(
716	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND id <> ?",
717	                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
718	        return n != null && n > 0;
719	    }
720	
721	    public Person insert(String sheetId, String name, String grade) {
722	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
723	        jdbc.update(con -> {
724	            PreparedStatement ps = con.prepareStatement(
725	                    "INSERT INTO person (sheet_id, name, grade) VALUES (?, ?, ?)", new String[] { "id" });
726	            ps.setString(1, sheetId);
727	            ps.setString(2, name);
728	            ps.setString(3, grade);
729	            return ps;
730	        }, keys);
731	        return new Person(keys.getKey().longValue(), sheetId, name, grade, 0);
732	    }
733	
734	    /** Saves the person if it is still at the version it was loaded at, moving it to the next
735	     *  version; false (nothing written) when someone else saved it in the meantime. */
736	    public boolean update(Person person) {
737	        int n = jdbc.update("UPDATE person SET name = ?, grade = ?, version = version + 1 WHERE id = ? AND version = ?",
738	                person.getName(), person.getGrade(), person.getId(), person.getVersion());
739	        if (n == 0) {
740	            return false;
741	        }
742	        person.setVersion(person.getVersion() + 1);
743	        return true;
744	    }
745	}
