847	import java.io.IOException;
848	import java.io.UncheckedIOException;
849	import java.nio.charset.StandardCharsets;
850	import java.nio.file.Files;
851	import java.nio.file.Path;
852	import java.nio.file.StandardOpenOption;
853	import org.springframework.beans.factory.annotation.Value;
854	import org.springframework.stereotype.Service;
855	
856	/**
857	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
858	 * so tests can assert side-effects by reading that file — the second test-assertion channel
859	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
860	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
861	 *
862	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
863	 * SYNC) so a test reads the record immediately.
864	 */
865	@Service
866	public class Audit {
867	
868	    private final Path file;
869	
870	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
871	        this.file = Path.of(path);
872	    }
873	
874	    /** Append one audit record. Tests assert the exact line(s) in the file. */
875	    public synchronized void record(String entry) {
876	        try {
877	            Path parent = file.toAbsolutePath().getParent();
878	            if (parent != null) {
879	                Files.createDirectories(parent);
880	            }
881	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
882	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
883	        } catch (IOException e) {
884	            throw new UncheckedIOException(e);
885	        }
886	    }
887	
888	    /** Remove the audit file. */
889	    public synchronized void clear() {
890	        try {
891	            Files.deleteIfExists(file);
892	        } catch (IOException e) {
893	            throw new UncheckedIOException(e);
894	        }
895	    }
896	}
